const stdout = $input.first().json.stdout;
let health;

try {
  health = JSON.parse(stdout);
} catch (e) {
  return [{
    json: {
      error: 'Failed to parse health-check output',
      raw_output: stdout,
      disk_used_pct: 0,
      backup_age_hours: 0,
      cpu_load: 0,
      memory_used_pct: 0,
      pg_connections: 0,
      n8n_status: 'unknown',
      checked_at: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    disk_used_pct: health.disk_used_pct || 0,
    backup_age_hours: health.backup_age_hours || 0,
    cpu_load: health.cpu_load || 0,
    memory_used_pct: health.memory_used_pct || 0,
    pg_connections: health.pg_connections || 0,
    n8n_status: health.n8n_status || 'unknown',
    uptime_seconds: health.uptime_seconds || 0,
    checked_at: new Date().toISOString()
  }
}];
